markdownrx_ts = r'''
// lib/markdownrx.ts
import { unified } from "unified";
import remarkParse from "remark-parse";
import remarkGfm from "remark-gfm";
import remarkSlug from "remark-slug";
import remarkRehype from "remark-rehype";
import rehypeAutolinkHeadings from "rehype-autolink-headings";
import rehypeHighlight from "rehype-highlight";
import rehypeStringify from "rehype-stringify";
import rehypeSanitize from "rehype-sanitize";
import { defaultSchema } from "hast-util-sanitize";

export type MarkdownRXOptions = {
  gfm?: boolean;
  highlight?: boolean;
  sanitize?: boolean;
};

const extendedSchema: any = {
  ...defaultSchema,
  attributes: {
    ...defaultSchema.attributes,
    code: [
      ...(defaultSchema.attributes?.code || []),
      ["className"],
    ],
    span: [
      ...(defaultSchema.attributes?.span || []),
      ["className"],
    ],
    a: [
      ...(defaultSchema.attributes?.a || []),
      ["className", "ariaHidden", "tabIndex"],
    ],
  },
};

export async function markdownToHtml(
  markdown: string,
  options: MarkdownRXOptions = {}
): Promise<string> {
  const { gfm = true, highlight = true, sanitize = true } = options;

  const processor = unified().use(remarkParse);
  if (gfm) processor.use(remarkGfm);

  processor.use(remarkSlug);
  processor.use(remarkRehype, {
    allowDangerousHtml: false, // disable raw HTML in markdown for safety
  });

  if (sanitize) {
    processor.use(rehypeSanitize, extendedSchema);
  }

  if (highlight) {
    processor.use(rehypeHighlight);
  }

  processor.use(rehypeAutolinkHeadings, { behavior: "wrap" });
  processor.use(rehypeStringify);

  const file = await processor.process(markdown || "");
  return String(file);
}
'''
