docs_index_page_tsx = r'''
import { db } from "@/lib/firebase";
import { collection, getDocs, query, orderBy } from "firebase/firestore";
import Link from "next/link";

export const dynamic = "force-dynamic"; // simple approach for demo

async function getDocsList() {
  const q = query(collection(db, "docs"), orderBy("updatedAt", "desc"));
  const snap = await getDocs(q);
  return snap.docs.map((d) => ({ id: d.id, ...(d.data() as any) }));
}

export default async function DocsIndexPage() {
  const items = await getDocsList();
  return (
    <div className="mx-auto max-w-4xl space-y-6 p-6">
      <div className="flex items-center justify-between gap-2">
        <h1 className="text-2xl font-bold">Documentation</h1>
        <Link className="rounded border px-3 py-2" href="/docs/new">New</Link>
      </div>
      <ul className="divide-y rounded border">
        {items.map((it) => (
          <li key={it.id} className="flex items-center justify-between p-3 hover:bg-muted/40">
            <div>
              <div className="font-medium">{it.title || it.id}</div>
              <div className="text-sm text-muted-foreground">/{it.id}</div>
            </div>
            <Link className="rounded border px-3 py-1" href={`/docs/${it.id}`}>Open</Link>
          </li>
        ))}
      </ul>
    </div>
  );
}
'''
