"use client";
import * as React from "react";
import { useRouter, useParams } from "next/navigation";
import { db, storage } from "@/lib/firebase";
import { doc, onSnapshot, setDoc, updateDoc, deleteDoc, getDoc, serverTimestamp } from "firebase/firestore";
import { ref, uploadBytes, getDownloadURL } from "firebase/storage";
import { MarkdownRXEditor, MarkdownRXPreview } from "@/components/MarkdownRX";

function slugify(input: string) {
  return input.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)+/g, "");
}

export default function DocPage() {
  const params = useParams();
  const router = useRouter();
  const slug = String(params.slug);

  const [title, setTitle] = React.useState("");
  const [content, setContent] = React.useState("");
  const [tagsText, setTagsText] = React.useState("");
  const [loading, setLoading] = React.useState(true);
  const [saving, setSaving] = React.useState(false);

  React.useEffect(() => {
    const refDoc = doc(db, "docs", slug);
    const unsub = onSnapshot(refDoc, (snap) => {
      if (snap.exists()) {
        const d: any = snap.data();
        setTitle(d.title || "");
        setContent(d.content || "");
        setTagsText((d.tags || []).join(", "));
      }
      setLoading(false);
    });
    return () => unsub();
  }, [slug]);

  async function onUploadImage(file: File) {
    const path = `docs/${slug}/images/${Date.now()}-${file.name}`;
    const storageRef = ref(storage, path);
    await uploadBytes(storageRef, file);
    return await getDownloadURL(storageRef);
  }

  function buildOutline(md: string) {
    return (md.match(/^#{1,6}\s+.*$/gm) || []).map((line) => {
      const m = line.match(/^(#{1,6})\s+(.*)$/);
      if (!m) return null;
      const level = m[1].length;
      const text = m[2].trim();
      return { level, text };
    }).filter(Boolean) as { level: number; text: string }[];
  }

  function normalizeContent(t: string, c: string) {
    const noLeadingH1 = c.replace(/^#\s+.*\n+/, "");
    const header = `# ${t}\n\n`;
    let body = noLeadingH1
      .replace(/\n{3,}/g, "\n\n") // collapse blank lines
      .replace(/\s+$/g, ""); // trim trailing space
    if (!body.endsWith("\n")) body += "\n"; // EOF newline
    return header + body;
  }

  async function save() {
    setSaving(true);
    const next = normalizeContent(title || "Untitled", content || "");
    await setDoc(doc(db, "docs", slug), {
      title: title || "Untitled",
      content: next,
      tags: tagsText.split(",").map((s) => s.trim()).filter(Boolean),
      updatedAt: serverTimestamp(),
    }, { merge: true });
    setSaving(false);
  }

  async function rename(newTitle: string) {
    const newSlug = slugify(newTitle);
    if (!newSlug || newSlug === slug) return;
    const curRef = doc(db, "docs", slug);
    const newRef = doc(db, "docs", newSlug);
    const snap = await getDoc(curRef);
    if (!snap.exists()) return;
    const d = snap.data();
    await setDoc(newRef, { ...d, title: newTitle, updatedAt: serverTimestamp() });
    await deleteDoc(curRef);
    router.replace(`/docs/${newSlug}`);
  }

  async function removeDoc() {
    await deleteDoc(doc(db, "docs", slug));
    router.push("/docs");
  }

  const outline = buildOutline(content);

  if (loading) return <div className="p-6">Loading…</div>;

  return (
    <div className="p-6 grid grid-cols-1 lg:grid-cols-[1fr_300px] gap-6">
      <div className="space-y-4">
        <div className="flex flex-col gap-2">
          <input
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            className="border rounded px-3 py-2 text-xl font-semibold"
            placeholder="Document title"
          />
          <input
            value={tagsText}
            onChange={(e) => setTagsText(e.target.value)}
            className="border rounded px-3 py-2 text-sm"
            placeholder="tags: comma, separated"
          />
          <div className="flex gap-2">
            <button onClick={save} className="border rounded px-3 py-2" disabled={saving}>{saving ? "Saving…" : "Save"}</button>
            <button onClick={() => rename(title)} className="border rounded px-3 py-2">Rename to title</button>
            <button onClick={removeDoc} className="border rounded px-3 py-2 text-red-600">Delete</button>
          </div>
        </div>
        <MarkdownRXEditor value={content} onChange={setContent} onUploadImage={onUploadImage} />
        <div className="rounded border p-4">
          <div className="text-sm text-muted-foreground mb-2">Preview</div>
          <MarkdownRXPreview value={normalizeContent(title || "Untitled", content || "")} />
        </div>
      </div>
      <aside className="space-y-3">
        <div className="font-medium">Outline</div>
        <ul className="text-sm space-y-1">
          {outline.map((h, i) => (
            <li key={i} className={`pl-${(h.level - 1) * 2}`.trim()}>
              <span className="text-muted-foreground">{Array(h.level - 1).fill("• ").join("")}</span>
              {h.text}
            </li>
          ))}
        </ul>
        <div className="text-sm text-muted-foreground">
          Save will enforce a single H1 from the title and normalize spacing/newlines for consistent docs.
        </div>
      </aside>
    </div>
  );
}

