"use client";

import * as React from "react";
import { markdownToHtml } from "@/lib/markdownrx";

type PreviewProps = {
  value: string;
  className?: string;
  options?: Parameters<typeof markdownToHtml>[1];
};

export function MarkdownRXPreview({ value, className, options }: PreviewProps) {
  const [html, setHtml] = React.useState<string>("");

  React.useEffect(() => {
    let cancelled = false;
    markdownToHtml(value || "", options)
      .then((out) => {
        if (!cancelled) setHtml(out);
      })
      .catch(() => {
        if (!cancelled) setHtml("<pre>Failed to render markdown.</pre>");
      });
    return () => {
      cancelled = true;
    };
  }, [value, options]);

  return (
    <div
      className={["prose max-w-none", className].filter(Boolean).join(" ")}
      dangerouslySetInnerHTML={{ __html: html }}
    />
  );
}

type EditorProps = {
  value: string;
  onChange: (value: string) => void;
  onUploadImage?: (file: File) => Promise<string>; // returns a URL to insert
  className?: string;
};

type Mode = "edit" | "preview" | "split";

export function MarkdownRXEditor({
  value,
  onChange,
  onUploadImage,
  className,
}: EditorProps) {
  const [mode, setMode] = React.useState<Mode>("split");
  const textareaRef = React.useRef<HTMLTextAreaElement | null>(null);

  function insertAtCursor(snippet: string) {
    const ta = textareaRef.current;
    if (!ta) return;
    const start = ta.selectionStart ?? 0;
    const end = ta.selectionEnd ?? 0;
    const next = value.slice(0, start) + snippet + value.slice(end);
    onChange(next);
    requestAnimationFrame(() => {
      ta.focus();
      const cursor = start + snippet.length;
      ta.setSelectionRange(cursor, cursor);
    });
  }

  function wrapSelection(before: string, after: string = before) {
    const ta = textareaRef.current;
    if (!ta) return;
    const start = ta.selectionStart ?? 0;
    const end = ta.selectionEnd ?? 0;
    const selected = value.slice(start, end);
    const next = value.slice(0, start) + before + selected + after + value.slice(end);
    onChange(next);
    requestAnimationFrame(() => {
      ta.focus();
      const cursor = start + before.length + selected.length + after.length;
      ta.setSelectionRange(cursor, cursor);
    });
  }

  async function onPickImage(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    if (!file || !onUploadImage) return;
    try {
      const url = await onUploadImage(file);
      const alt = file.name.replace(/\.\w+$/, "");
      const snippet = `![${alt}](${url})`;
      insertAtCursor(snippet);
    } catch (err) {
      console.error("Upload failed", err);
    } finally {
      e.target.value = "";
    }
  }

  const toolbar = (
    <div className="flex flex-wrap items-center gap-2 border-b bg-muted/40 px-2 py-2">
      <div className="flex gap-1">
        <button className="rounded border px-2 py-1 text-sm" onClick={() => insertAtCursor("# ")}>H1</button>
        <button className="rounded border px-2 py-1 text-sm" onClick={() => insertAtCursor("## ")}>H2</button>
        <button className="rounded border px-2 py-1 text-sm" onClick={() => insertAtCursor("### ")}>H3</button>
      </div>
      <div className="flex gap-1">
        <button className="rounded border px-2 py-1 text-sm" onClick={() => wrapSelection("**", "**")}>Bold</button>
        <button className="rounded border px-2 py-1 text-sm" onClick={() => wrapSelection("_", "_")}>Italic</button>
        <button className="rounded border px-2 py-1 text-sm" onClick={() => wrapSelection("`", "`")}>Code</button>
      </div>
      <div className="flex gap-1">
        <button className="rounded border px-2 py-1 text-sm" onClick={() => insertAtCursor("> ")}>Quote</button>
        <button className="rounded border px-2 py-1 text-sm" onClick={() => insertAtCursor("- ")}>UL</button>
        <button className="rounded border px-2 py-1 text-sm" onClick={() => insertAtCursor("1. ")}>OL</button>
        <button className="rounded border px-2 py-1 text-sm" onClick={() => wrapSelection("```\n", "\n```")}>Code Block</button>
        <button
          className="rounded border px-2 py-1 text-sm"
          onClick={() => insertAtCursor("| Column A | Column B |\n| --- | --- |\n|  |  |\n")}
        >
          Table
        </button>
      </div>
      <div className="flex gap-1">
        <button className="rounded border px-2 py-1 text-sm" onClick={() => wrapSelection("[", "](https://)")}>Link</button>
        <label className="rounded border px-2 py-1 text-sm cursor-pointer">
          Image
          <input type="file" accept="image/*" className="hidden" onChange={onPickImage} />
        </label>
      </div>

      <div className="ml-auto flex gap-1">
        <button
          className={`rounded px-2 py-1 text-sm border ${mode === "edit" ? "bg-primary text-white" : ""}`}
          onClick={() => setMode("edit")}
        >
          Edit
        </button>
        <button
          className={`rounded px-2 py-1 text-sm border ${mode === "preview" ? "bg-primary text-white" : ""}`}
          onClick={() => setMode("preview")}
        >
          Preview
        </button>
        <button
          className={`rounded px-2 py-1 text-sm border ${mode === "split" ? "bg-primary text-white" : ""}`}
          onClick={() => setMode("split")}
        >
          Split
        </button>
      </div>
    </div>
  );

  const editor = (
    <textarea
      ref={textareaRef}
      value={value}
      onChange={(e) => onChange(e.target.value)}
      className="h-[60vh] w-full resize-none border-0 p-3 outline-none"
      placeholder="# Write your documentation..."
    />
  );

  const preview = (
    <div className="h-[60vh] overflow-auto border-l p-4">
      <MarkdownRXPreview value={value} />
    </div>
  );

  return (
    <div className={["rounded-md border bg-card shadow-sm", className].filter(Boolean).join(" ")}>
      {toolbar}
      {mode === "edit" && <div>{editor}</div>}
      {mode === "preview" && <div className="p-3"><MarkdownRXPreview value={value} /></div>}
      {mode === "split" && (
        <div className="grid grid-cols-1 md:grid-cols-2">
          {editor}
          {preview}
        </div>
      )}
    </div>
  );
}
'''
