"use client";

import * as React from "react";
import { db, storage } from "@/lib/firebase";
import { doc, onSnapshot, setDoc, serverTimestamp } from "firebase/firestore";
import { ref, uploadBytes, getDownloadURL } from "firebase/storage";
import { MarkdownRXEditor, MarkdownRXPreview } from "@/components/MarkdownRX";

type DocData = {
  title: string;
  content: string;
  tags?: string[];
  createdAt?: any;
  updatedAt?: any;
};

export default function DocEditor({ slug }: { slug: string }) {
  const [data, setData] = React.useState<DocData | null>(null);
  const [title, setTitle] = React.useState("");
  const [content, setContent] = React.useState("");
  const [saving, setSaving] = React.useState(false);
  const [lastSavedAt, setLastSavedAt] = React.useState<Date | null>(null);

  // Live subscribe to Firestore document
  React.useEffect(() => {
    const refDoc = doc(db, "docs", slug);
    const unsub = onSnapshot(refDoc, (snap) => {
      if (!snap.exists()) {
        setData(null);
        setTitle("");
        setContent("");
        return;
      }
      const d = snap.data() as DocData;
      setData(d);
      setTitle(d.title || slug);
      setContent(d.content || "");
    });
    return () => unsub();
  }, [slug]);

  async function save() {
    setSaving(true);
    try {
      await setDoc(
        doc(db, "docs", slug),
        {
          title: title || slug,
          content,
          updatedAt: serverTimestamp(),
          createdAt: data?.createdAt || serverTimestamp(),
        },
        { merge: true }
      );
      setLastSavedAt(new Date());
    } finally {
      setSaving(false);
    }
  }

  async function uploadImage(file: File) {
    const storagePath = `docs/${slug}/${Date.now()}-${file.name}`;
    const storageRef = ref(storage, storagePath);
    await uploadBytes(storageRef, file, { contentType: file.type });
    return getDownloadURL(storageRef);
  }

  return (
    <div className="space-y-4">
      <div className="flex flex-col gap-2 md:flex-row md:items-center">
        <input
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          placeholder="Document title"
          className="w-full rounded border px-3 py-2"
        />
        <button
          onClick={save}
          disabled={saving}
          className="ml-auto rounded border bg-primary px-3 py-2 text-white disabled:opacity-50"
        >
          {saving ? "Saving..." : "Save"}
        </button>
        {lastSavedAt && (
          <span className="text-xs text-muted-foreground">Saved {lastSavedAt.toLocaleTimeString()}</span>
        )}
      </div>

      <MarkdownRXEditor value={content} onChange={setContent} onUploadImage={uploadImage} />

      <div className="rounded-md border p-4">
        <h2 className="mb-2 text-lg font-semibold">Preview</h2>
        <MarkdownRXPreview value={content} />
      </div>
    </div>
  );
}
'''
