#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll INF = (1LL<<62);

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k;
    if(!(cin >> n >> m >> k)) return 0;

    vector<vector<pair<int,int>>> g(n+1);
    g.reserve(n+1);
    for(int i=0;i<m;++i){
        int u,v; int w;
        cin >> u >> v >> w;
        g[u].push_back({v,w});
        g[v].push_back({u,w});
    }

    auto dijkstra = [&](int src){
        vector<ll> dist(n+1, INF);
        priority_queue<pair<ll,int>, vector<pair<ll,int>>, greater<pair<ll,int>>> pq;
        dist[src] = 0;
        pq.push({0, src});
        while(!pq.empty()){
            auto [d,u] = pq.top(); pq.pop();
            if(d != dist[u]) continue;
            for(auto [v,w] : g[u]){
                ll nd = d + (ll)w;
                if(nd < dist[v]){
                    dist[v] = nd;
                    pq.push({nd, v});
                }
            }
        }
        return dist;
    };

    // Shortest path distances in kilometers (edge weights are km)
    vector<ll> d1 = dijkstra(1);
    vector<ll> dn = dijkstra(n);

    // Ensure graph connectivity from 1 to n as stated, but still safe-guard
    // Precompute for each node i the pair (d1[i], dn[i])

    // Process k days
    // For each day with times per km a (Thuan) and b (Dong), the arrival times at node i are:
    //   T1 = d1[i] * a, Tn = dn[i] * b (in seconds). We minimize max(T1, Tn) over i.
    // Output minimal waiting time = min_i |T1 - Tn|.

    // To compute efficiently for up to 1e5 days, we evaluate over all nodes per day (O(nk)).
    // This is acceptable only if constraints are small; but with given limits, we still must do O(nk).
    // However, we can optimize constant factors and use 64-bit safely.

    vector<pair<ll,ll>> dd; dd.reserve(n);
    for(int i=1;i<=n;++i){
        if(d1[i] == INF || dn[i] == INF) continue; // unreachable node is irrelevant
        dd.emplace_back(d1[i], dn[i]);
    }

    for(int day=0; day<k; ++day){
        ll a,b; cin >> a >> b;
        ll best = INF;
        for(const auto &p : dd){
            ll t1 = p.first;  // km
            ll t2 = p.second; // km
            // times per km are up to 1e6, distances up to about 1e11 (path length max m*1e6), use 128-bit
            __int128 A = (__int128)t1 * a;
            __int128 B = (__int128)t2 * b;
            __int128 diff = A - B;
            if(diff < 0) diff = -diff;
            if(diff < best) best = (ll)diff;
        }
        cout << best << '\n';
    }

    return 0;
}

Below is a complete, self-contained Tkinter application that manages the tournament’s scoring. It is organized, validated, and commented to be maintainable. It includes:
- Participants (Teams and Individuals) with “one event only” support and optional chosen event.
- Events (Team or Individual) with optional per-event points.
- Results entry per event via ranked ordering with strong validation.
- Leaderboards for teams and individuals.
- Points configuration (global schemes + custom editor).
- Save/Load/New via JSON with validation and clear error handling.

To run: save as a .py file and execute with Python 3.8+.

```python
import json
from dataclasses import dataclass, asdict, field
from typing import Dict, List, Optional, Tuple

import tkinter as tk
from tkinter import ttk, messagebox, filedialog


# -------------------------
# Data Model
# -------------------------

@dataclass
class Team:
    id: int
    name: str
    members: List[str] = field(default_factory=list)
    one_event_only: bool = False
    chosen_event_id: Optional[int] = None  # Applies if one_event_only is True


@dataclass
class Individual:
    id: int
    name: str
    one_event_only: bool = False
    chosen_event_id: Optional[int] = None  # Applies if one_event_only is True


@dataclass
class Event:
    id: int
    name: str
    type: str  # "Team" or "Individual"
    genre: str = ""
    points_map: Optional[Dict[int, int]] = None  # Per-event override


class TournamentData:
    """
    Core model for the tournament. Handles validation, CRUD operations,
    results storage, points aggregation, and JSON (de)serialization.
    """
    def __init__(self):
        self.teams: Dict[int, Team] = {}
        self.individuals: Dict[int, Individual] = {}
        self.events: Dict[int, Event] = {}
        # event_id -> ordered list of entrant IDs
        self.results: Dict[int, List[int]] = {}
        # Global points table (default: F1 Top 10)
        self.points_map: Dict[int, int] = {
            1: 25, 2: 18, 3: 15, 4: 12, 5: 10, 6: 8, 7: 6, 8: 4, 9: 2, 10: 1
        }
        self.team_counter = 1
        self.indiv_counter = 1
        self.event_counter = 1

    # ---- Constraints ----
    def max_teams(self) -> int:
        return 4

    def max_team_members(self) -> int:
        return 5

    def max_individuals(self) -> int:
        return 20

    def max_events_per_type(self) -> int:
        # 5 Team events and 5 Individual events
        return 5

    # ---- Helpers ----
    @staticmethod
    def _clean_name(value: str) -> str:
        return (value or "").strip()

    def _validate_points_map(self, points: Dict[int, int]) -> None:
        if not isinstance(points, dict) or not points:
            raise ValueError("Points map must be a non-empty dictionary.")
        for k, v in points.items():
            if not isinstance(k, int) or k <= 0:
                raise ValueError("Rank keys must be positive integers.")
            if not isinstance(v, int) or v < 0:
                raise ValueError("Point values must be non-negative integers.")
        # Non-increasing across ranks: points[1] >= points[2] >= ...
        prev_points = None
        for r in sorted(points.keys()):
            if prev_points is not None and points[r] > prev_points:
                raise ValueError("Points should not increase for lower ranks.")
            prev_points = points[r]

    def get_points_for_event(self, event_id: int) -> Dict[int, int]:
        ev = self.events.get(event_id)
        if ev and ev.points_map:
            return ev.points_map
        return self.points_map

    # ---- CRUD for Teams ----
    def add_team(self, name: str, members: List[str], one_event_only: bool = False, chosen_event_id: Optional[int] = None) -> int:
        name = self._clean_name(name)
        if not name:
            raise ValueError("Team name cannot be empty.")
        if len(self.teams) >= self.max_teams():
            raise ValueError("Maximum number of teams reached (4).")
        if len(members) > self.max_team_members():
            raise ValueError("A team can have at most 5 members.")
        cleaned_members = [self._clean_name(m) for m in members if self._clean_name(m)]
        if not cleaned_members:
            raise ValueError("A team must have at least one member.")
        if any(t.name.lower() == name.lower() for t in self.teams.values()):
            raise ValueError("Team name must be unique.")
        if chosen_event_id is not None:
            ev = self.events.get(chosen_event_id)
            if ev is None or ev.type != "Team":
                raise ValueError("Chosen event must be a valid Team event.")
        team_id = self.team_counter
        self.team_counter += 1
        self.teams[team_id] = Team(id=team_id, name=name, members=cleaned_members,
                                   one_event_only=one_event_only, chosen_event_id=chosen_event_id)
        return team_id

    def edit_team(self, tid: int, name: str, members: List[str], one_event_only: bool, chosen_event_id: Optional[int]) -> None:
        if tid not in self.teams:
            raise ValueError("Team not found.")
        name = self._clean_name(name)
        if not name:
            raise ValueError("Team name cannot be empty.")
        if len(members) > self.max_team_members():
            raise ValueError("A team can have at most 5 members.")
        cleaned_members = [self._clean_name(m) for m in members if self._clean_name(m)]
        if not cleaned_members:
            raise ValueError("A team must have at least one member.")
        if chosen_event_id is not None:
            ev = self.events.get(chosen_event_id)
            if ev is None or ev.type != "Team":
                raise ValueError("Chosen event must be a valid Team event.")
        if any(t.name.lower() == name.lower() and t.id != tid for t in self.teams.values()):
            raise ValueError("Team name must be unique.")
        t = self.teams[tid]
        t.name = name
        t.members = cleaned_members
        t.one_event_only = one_event_only
        t.chosen_event_id = chosen_event_id

    def remove_team(self, tid: int) -> None:
        if tid not in self.teams:
            raise ValueError("Team not found.")
        # Remove from any Team event results
        for ev_id, places in list(self.results.items()):
            ev = self.events.get(ev_id)
            if ev and ev.type == "Team":
                self.results[ev_id] = [pid for pid in places if pid != tid]
        del self.teams[tid]

    # ---- CRUD for Individuals ----
    def add_individual(self, name: str, one_event_only: bool = False, chosen_event_id: Optional[int] = None) -> int:
        name = self._clean_name(name)
        if not name:
            raise ValueError("Individual name cannot be empty.")
        if len(self.individuals) >= self.max_individuals():
            raise ValueError("Maximum number of individuals reached (20).")
        if any(i.name.lower() == name.lower() for i in self.individuals.values()):
            raise ValueError("Individual name must be unique.")
        if chosen_event_id is not None:
            ev = self.events.get(chosen_event_id)
            if ev is None or ev.type != "Individual":
                raise ValueError("Chosen event must be a valid Individual event.")
        iid = self.indiv_counter
        self.indiv_counter += 1
        self.individuals[iid] = Individual(id=iid, name=name,
                                           one_event_only=one_event_only, chosen_event_id=chosen_event_id)
        return iid

    def edit_individual(self, iid: int, name: str, one_event_only: bool, chosen_event_id: Optional[int]) -> None:
        if iid not in self.individuals:
            raise ValueError("Individual not found.")
        name = self._clean_name(name)
        if not name:
            raise ValueError("Individual name cannot be empty.")
        if chosen_event_id is not None:
            ev = self.events.get(chosen_event_id)
            if ev is None or ev.type != "Individual":
                raise ValueError("Chosen event must be a valid Individual event.")
        if any(p.name.lower() == name.lower() and p.id != iid for p in self.individuals.values()):
            raise ValueError("Individual name must be unique.")
        person = self.individuals[iid]
        person.name = name
        person.one_event_only = one_event_only
        person.chosen_event_id = chosen_event_id

    def remove_individual(self, iid: int) -> None:
        if iid not in self.individuals:
            raise ValueError("Individual not found.")
        for ev_id, places in list(self.results.items()):
            ev = self.events.get(ev_id)
            if ev and ev.type == "Individual":
                self.results[ev_id] = [pid for pid in places if pid != iid]
        del self.individuals[iid]

    # ---- CRUD for Events ----
    def add_event(self, name: str, etype: str, genre: str = "", points_map: Optional[Dict[int, int]] = None) -> int:
        name = self._clean_name(name)
        if not name:
            raise ValueError("Event name cannot be empty.")
        if etype not in ("Team", "Individual"):
            raise ValueError("Event type must be 'Team' or 'Individual'.")
        count_type = sum(1 for e in self.events.values() if e.type == etype)
        if count_type >= self.max_events_per_type():
            raise ValueError(f"Maximum number of {etype} events reached (5).")
        if any(e.name.lower() == name.lower() for e in self.events.values()):
            raise ValueError("Event name must be unique.")
        if points_map:
            self._validate_points_map(points_map)
        eid = self.event_counter
        self.event_counter += 1
        self.events[eid] = Event(id=eid, name=name, type=etype, genre=self._clean_name(genre), points_map=points_map)
        return eid

    def edit_event(self, eid: int, name: str, etype: str, genre: str, points_map: Optional[Dict[int, int]]) -> None:
        if eid not in self.events:
            raise ValueError("Event not found.")
        name = self._clean_name(name)
        if not name:
            raise ValueError("Event name cannot be empty.")
        if etype not in ("Team", "Individual"):
            raise ValueError("Event type must be 'Team' or 'Individual'.")
        if any(e.name.lower() == name.lower() and e.id != eid for e in self.events.values()):
            raise ValueError("Event name must be unique.")
        if points_map:
            self._validate_points_map(points_map)
        old = self.events[eid]
        # If the type changes, clear any existing results (to avoid cross-type mismatch)
        if old.type != etype and eid in self.results:
            self.results[eid] = []
        old.name = name
        old.type = etype
        old.genre = self._clean_name(genre)
        old.points_map = points_map

    def remove_event(self, eid: int) -> None:
        if eid not in self.events:
            raise ValueError("Event not found.")
        # Remove results for this event
        self.results.pop(eid, None)
        # Clear chosen_event_id references
        for t in self.teams.values():
            if t.chosen_event_id == eid:
                t.chosen_event_id = None
        for i in self.individuals.values():
            if i.chosen_event_id == eid:
                i.chosen_event_id = None
        del self.events[eid]

    # ---- Results & Points ----
    def set_event_results(self, eid: int, ordered_participant_ids: List[int]) -> None:
        if eid not in self.events:
            raise ValueError("Event not found.")
        ev = self.events[eid]
        # Validate IDs match type
        valid_ids = set(self.teams.keys()) if ev.type == "Team" else set(self.individuals.keys())
        if any(pid not in valid_ids for pid in ordered_participant_ids):
            raise ValueError("Results contain invalid participant IDs for this event type.")
        # No duplicates
        if len(ordered_participant_ids) != len(set(ordered_participant_ids)):
            raise ValueError("Duplicate participant IDs in results.")
        # If one-event-only, ensure they are not in results of other events of same type unless it is their chosen event
        for pid in ordered_participant_ids:
            if ev.type == "Team":
                p = self.teams.get(pid)
            else:
                p = self.individuals.get(pid)
            if p and p.one_event_only:
                if p.chosen_event_id is None:
                    p.chosen_event_id = eid
                elif p.chosen_event_id != eid:
                    raise ValueError(f"Participant '{p.name}' is restricted to one event only.")
        self.results[eid] = list(ordered_participant_ids)

    def compute_leaderboards(self) -> Tuple[List[Tuple[int, int]], List[Tuple[int, int]]]:
        team_points: Dict[int, int] = {tid: 0 for tid in self.teams}
        indiv_points: Dict[int, int] = {iid: 0 for iid in self.individuals}
        for eid, placements in self.results.items():
            ev = self.events.get(eid)
            if not ev:
                continue
            pmap = self.get_points_for_event(eid)
            for rank, pid in enumerate(placements, start=1):
                pts = pmap.get(rank, 0)
                if ev.type == "Team":
                    if pid in team_points:
                        team_points[pid] += pts
                else:
                    if pid in indiv_points:
                        indiv_points[pid] += pts
        # Sort by points desc, then id asc for stability
        team_board = sorted(team_points.items(), key=lambda x: (-x[1], x[0]))
        indiv_board = sorted(indiv_points.items(), key=lambda x: (-x[1], x[0]))
        return team_board, indiv_board

    # ---- Serialization ----
    def to_json(self) -> str:
        payload = {
            "teams": [asdict(t) for t in self.teams.values()],
            "individuals": [asdict(i) for i in self.individuals.values()],
            "events": [asdict(e) for e in self.events.values()],
            "results": {str(k): v for k, v in self.results.items()},
            "points_map": self.points_map,
            "counters": {
                "team": self.team_counter,
                "indiv": self.indiv_counter,
                "event": self.event_counter,
            },
        }
        return json.dumps(payload, indent=2)

    @staticmethod
    def from_json(s: str) -> "TournamentData":
        data = json.loads(s)
        td = TournamentData()
        td.points_map = data.get("points_map", td.points_map)
        for t in data.get("teams", []):
            td.teams[t["id"]] = Team(**t)
        for i in data.get("individuals", []):
            td.individuals[i["id"]] = Individual(**i)
        for e in data.get("events", []):
            td.events[e["id"]] = Event(**e)
        td.results = {int(k): v for k, v in data.get("results", {}).items()}
        c = data.get("counters", {})
        td.team_counter = int(c.get("team", td.team_counter))
        td.indiv_counter = int(c.get("indiv", td.indiv_counter))
        td.event_counter = int(c.get("event", td.event_counter))
        return td


# -------------------------
# Tkinter Application
# -------------------------

class TournamentApp(tk.Tk):
    """Tkinter GUI to manage teams, individuals, events, results, and leaderboards."""

    def __init__(self):
        super().__init__()
        self.title("E-sports Tournament Manager")
        self.geometry("1100x700")
        self.minsize(1000, 650)
        self.td = TournamentData()
        self._build_menu()
        self._build_layout()

    # ---- Menu ----
    def _build_menu(self):
        menubar = tk.Menu(self)
        file_menu = tk.Menu(menubar, tearoff=0)
        file_menu.add_command(label="New", command=self._new_data)
        file_menu.add_command(label="Open...", command=self._open)
        file_menu.add_command(label="Save As...", command=self._save_as)
        file_menu.add_separator()
        file_menu.add_command(label="Exit", command=self.destroy)
        menubar.add_cascade(label="File", menu=file_menu)

        points_menu = tk.Menu(menubar, tearoff=0)
        points_menu.add_command(label="Edit Global Points...", command=self._edit_global_points)
        menubar.add_cascade(label="Points", menu=points_menu)

        self.config(menu=menubar)

    # ---- Layout ----
    def _build_layout(self):
        nb = ttk.Notebook(self)
        nb.pack(fill=tk.BOTH, expand=True)

        self.frame_participants = ttk.Frame(nb)
        self.frame_events = ttk.Frame(nb)
        self.frame_results = ttk.Frame(nb)
        self.frame_leaderboard = ttk.Frame(nb)

        nb.add(self.frame_participants, text="Participants")
        nb.add(self.frame_events, text="Events")
        nb.add(self.frame_results, text="Results")
        nb.add(self.frame_leaderboard, text="Leaderboards")

        self._build_participants_tab()
        self._build_events_tab()
        self._build_results_tab()
        self._build_leaderboard_tab()

    # ---- Participants Tab ----
    def _build_participants_tab(self):
        paned = ttk.Panedwindow(self.frame_participants, orient=tk.HORIZONTAL)
        paned.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)

        # Teams panel
        team_frame = ttk.Labelframe(paned, text="Teams")
        paned.add(team_frame, weight=1)
        self._team_tree = ttk.Treeview(team_frame, columns=("name", "members", "one", "chosen"), show="headings", height=12)
        for col, txt, w in (("name", "Name", 150), ("members", "Members (comma)", 250), ("one", "One-Event", 90), ("chosen", "Chosen Event", 150)):
            self._team_tree.heading(col, text=txt)
            self._team_tree.column(col, width=w, anchor=tk.W)
        self._team_tree.pack(fill=tk.X, padx=5, pady=5)

        tform = ttk.Frame(team_frame)
        tform.pack(fill=tk.X, padx=5, pady=5)
        ttk.Label(tform, text="Name").grid(row=0, column=0, sticky=tk.W)
        ttk.Label(tform, text="Members (comma-separated)").grid(row=0, column=2, sticky=tk.W)
        self.team_name = ttk.Entry(tform, width=20)
        self.team_members = ttk.Entry(tform, width=40)
        self.team_one_only = tk.BooleanVar(value=False)
