        ttk.Button(btns, text="Save Results", command=self._save_results_for_event).pack(fill=tk.X, pady=15)

        # Guidance
        note = ttk.Label(frame, foreground="#555",
                         text="Tip: Load Entrants, then arrange order to reflect ranks (top=1st). One-event-only participants can only appear in their chosen/single event.")
