    # ---- Leaderboard Tab ----
    def _build_leaderboard_tab(self):
        frame = self.frame_leaderboard
        top = ttk.Frame(frame)
        top.pack(fill=tk.X, padx=10, pady=8)
        ttk.Button(top, text="Refresh", command=self._refresh_leaderboards).pack(side=tk.LEFT)

        panes = ttk.Panedwindow(frame, orient=tk.HORIZONTAL)
