    # -------------------------
    # Menu actions
    # -------------------------
    def _new_data(self):
        if messagebox.askyesno("Confirm", "Clear all data?"):
            self.td = TournamentData()
            self._refresh_all()

    def _open(self):
        path = filedialog.askopenfilename(filetypes=[["JSON Files", "*.json"], ["All Files", "*.*"]])
        if not path:
            return
        try:
            with open(path, "r", encoding="utf-8") as f:
                self.td = TournamentData.from_json(f.read())
            self._refresh_all()
        except Exception as e:
            messagebox.showerror("Load Error", str(e))

    def _save_as(self):
        path = filedialog.asksaveasfilename(defaultextension=".json", filetypes=[["JSON Files", "*.json"]])
        if not path:
            return
        try:
            with open(path, "w", encoding="utf-8") as f:
                f.write(self.td.to_json())
            messagebox.showinfo("Saved", "Data saved successfully.")
        except Exception as e:
            messagebox.showerror("Save Error", str(e))

    def _edit_global_points(self):
        dlg = tk.Toplevel(self)
        dlg.title("Edit Global Points")
        ttk.Label(dlg, text="Define rank->points as 'rank:points' per line (e.g., 1:25)\nRanks must be positive integers; points non-negative and non-increasing.").pack(padx=10, pady=8)
        txt = tk.Text(dlg, width=40, height=12)
        txt.pack(padx=10, pady=8)
        # Seed
        lines = [f"{r}:{p}" for r, p in sorted(self.td.points_map.items())]
        txt.insert("1.0", "\n".join(lines))

        def save():
            try:
                content = txt.get("1.0", tk.END).strip()
                pm: Dict[int, int] = {}
                if content:
                    for line in content.splitlines():
                        if not line.strip():
                            continue
                        r_s, p_s = [x.strip() for x in line.split(":", 1)]
                        r, p = int(r_s), int(p_s)
                        pm[r] = p
                self.td._validate_points_map(pm)
                self.td.points_map = pm
                messagebox.showinfo("Updated", "Global points updated.")
                dlg.destroy()
            except Exception as e:
                messagebox.showerror("Invalid Points", str(e))

        ttk.Button(dlg, text="Save", command=save).pack(pady=6)

    # -------------------------
    # Participants handlers
    # -------------------------
    def _refresh_event_dropdowns(self, *_):
        # Populate chosen-event comboboxes
        team_events = [e for e in self.td.events.values() if e.type == "Team"]
        indiv_events = [e for e in self.td.events.values() if e.type == "Individual"]
        self.team_chosen_event["values"] = [f"{e.id}: {e.name}" for e in team_events]
        self.indiv_chosen_event["values"] = [f"{e.id}: {e.name}" for e in indiv_events]

        # Results tab events
        all_events = [f"{e.id}: {e.name} [{e.type}]" for e in self.td.events.values()]
        self.res_event["values"] = all_events

        # Events tree
        self._refresh_events_tree()

    def _parse_event_combo_value(self, val: str) -> Optional[int]:
        if not val:
            return None
        try:
            return int(val.split(":", 1)[0])
        except Exception:
            return None

    def _add_update_team(self):
        try:
            name = self.team_name.get()
            members = [m.strip() for m in self.team_members.get().split(",") if m.strip()]
            one = bool(self.team_one_only.get())
            chosen_id = self._parse_event_combo_value(self.team_chosen_event.get())
            # If one-event-only is False, ignore chosen_id
            if not one:
                chosen_id = None
            # Update if a row is selected (match by name), else add
            existing = None
            for tid, t in self.td.teams.items():
                if t.name.strip().lower() == (name or "").strip().lower():
                    existing = tid
                    break
            if existing is None:
                self.td.add_team(name, members, one, chosen_id)
            else:
                self.td.edit_team(existing, name, members, one, chosen_id)
            self._refresh_participants_trees()
            self.team_name.delete(0, tk.END)
            self.team_members.delete(0, tk.END)
            self.team_one_only.set(False)
            self.team_chosen_event.set("")
        except Exception as e:
            messagebox.showerror("Team Error", str(e))

    def _remove_team(self):
        sel = self._team_tree.selection()
        if not sel:
            return
        item = sel[0]
        values = self._team_tree.item(item, "values")
        name = values[0]
        for tid, t in list(self.td.teams.items()):
            if t.name == name:
                try:
                    self.td.remove_team(tid)
                except Exception as e:
                    messagebox.showerror("Remove Error", str(e))
                break
        self._refresh_participants_trees()

    def _add_update_individual(self):
        try:
            name = self.indiv_name.get()
            one = bool(self.indiv_one_only.get())
            chosen_id = self._parse_event_combo_value(self.indiv_chosen_event.get())
            if not one:
                chosen_id = None
            # Update if exists by name
            existing = None
            for iid, p in self.td.individuals.items():
                if p.name.strip().lower() == (name or "").strip().lower():
                    existing = iid
                    break
            if existing is None:
                self.td.add_individual(name, one, chosen_id)
            else:
                self.td.edit_individual(existing, name, one, chosen_id)
            self._refresh_participants_trees()
            self.indiv_name.delete(0, tk.END)
            self.indiv_one_only.set(False)
            self.indiv_chosen_event.set("")
        except Exception as e:
            messagebox.showerror("Individual Error", str(e))

    def _remove_individual(self):
        sel = self._indiv_tree.selection()
        if not sel:
            return
        item = sel[0]
        values = self._indiv_tree.item(item, "values")
        name = values[0]
        for iid, p in list(self.td.individuals.items()):
            if p.name == name:
                try:
                    self.td.remove_individual(iid)
                except Exception as e:
                    messagebox.showerror("Remove Error", str(e))
                break
        self._refresh_participants_trees()

    def _refresh_participants_trees(self):
        # Teams
        for i in self._team_tree.get_children():
            self._team_tree.delete(i)
        for t in self.td.teams.values():
            chosen = self.td.events.get(t.chosen_event_id).name if t.chosen_event_id in self.td.events else ""
            self._team_tree.insert("", tk.END, values=(t.name, ", ".join(t.members), "Yes" if t.one_event_only else "No", chosen))
        # Individuals
        for i in self._indiv_tree.get_children():
            self._indiv_tree.delete(i)
        for p in self.td.individuals.values():
            chosen = self.td.events.get(p.chosen_event_id).name if p.chosen_event_id in self.td.events else ""
            self._indiv_tree.insert("", tk.END, values=(p.name, "Yes" if p.one_event_only else "No", chosen))

    # -------------------------
    # Events handlers
    # -------------------------
    def _parse_points_override(self, s: str) -> Optional[Dict[int, int]]:
        s = (s or "").strip()
        if not s:
            return None
        out: Dict[int, int] = {}
        try:
            for part in s.split(','):
                k, v = [x.strip() for x in part.split(':', 1)]
                out[int(k)] = int(v)
            self.td._validate_points_map(out)
            return out
        except Exception as e:
            raise ValueError(f"Invalid points override: {e}")

    def _add_update_event(self):
        try:
            name = self.ev_name.get()
            etype = self.ev_type.get()
            genre = self.ev_genre.get()
            pmap = self._parse_points_override(self.ev_points_override.get())
            # Update if exists by name
            existing = None
            for eid, e in self.td.events.items():
                if e.name.strip().lower() == (name or "").strip().lower():
                    existing = eid
                    break
            if existing is None:
                self.td.add_event(name, etype, genre, pmap)
            else:
                self.td.edit_event(existing, name, etype, genre, pmap)
            self._refresh_events_tree()
            self._refresh_event_dropdowns()
            self.ev_name.delete(0, tk.END)
            self.ev_genre.delete(0, tk.END)
            self.ev_points_override.delete(0, tk.END)
        except Exception as e:
            messagebox.showerror("Event Error", str(e))

    def _remove_event(self):
        sel = self._event_tree.selection()
        if not sel:
            return
        item = sel[0]
        name = self._event_tree.item(item, "values")[0]
        for eid, e in list(self.td.events.items()):
            if e.name == name:
                try:
                    self.td.remove_event(eid)
                except Exception as ex:
                    messagebox.showerror("Remove Error", str(ex))
                break
        self._refresh_events_tree()
        self._refresh_event_dropdowns()

    def _refresh_events_tree(self):
        for i in self._event_tree.get_children():
            self._event_tree.delete(i)
        for e in sorted(self.td.events.values(), key=lambda x: x.id):
            override = (
                ", ".join(f"{r}:{p}" for r, p in sorted(e.points_map.items())) if e.points_map else ""
            )
            self._event_tree.insert("", tk.END, values=(e.name, e.type, e.genre, override))

    # -------------------------
    # Results handlers
    # -------------------------
    def _load_entrants_for_event(self):
        try:
            eid = self._parse_event_combo_value(self.res_event.get())
            if eid is None or eid not in self.td.events:
                raise ValueError("Select a valid event.")
            ev = self.td.events[eid]
            self._clear_tree(self._entrants_tree)
            # Preload existing results if any; else populate all eligible entrants
            if eid in self.td.results and self.td.results[eid]:
                source_ids = self.td.results[eid]
            else:
                if ev.type == "Team":
                    source_ids = list(self.td.teams.keys())
                else:
                    source_ids = list(self.td.individuals.keys())
                # Filter one-event-only participants who already chose a different event
                filtered = []
                for pid in source_ids:
                    p = self.td.teams.get(pid) if ev.type == "Team" else self.td.individuals.get(pid)
                    if p and p.one_event_only and p.chosen_event_id is not None and p.chosen_event_id != eid:
                        continue
                    filtered.append(pid)
                source_ids = filtered
            for pid in source_ids:
                name = (self.td.teams.get(pid).name if ev.type == "Team" else self.td.individuals.get(pid).name)
                self._entrants_tree.insert("", tk.END, values=(pid, name))
        except Exception as e:
            messagebox.showerror("Load Entrants Error", str(e))

    def _move_entrant(self, delta: int):
        sel = self._entrants_tree.selection()
        if not sel:
            return
        item = sel[0]
        index = self._entrants_tree.index(item)
        new_index = max(0, index + delta)
        if new_index == index:
            return
        self._entrants_tree.move(item, "", new_index)

    def _remove_entrant_from_list(self):
        sel = self._entrants_tree.selection()
        if not sel:
            return
        self._entrants_tree.delete(sel[0])

    def _add_eligible_dialog(self):
        eid = self._parse_event_combo_value(self.res_event.get())
        if eid is None or eid not in self.td.events:
            messagebox.showerror("Select Event", "Select an event first.")
            return
        ev = self.td.events[eid]
        top = tk.Toplevel(self)
        top.title("Add Eligible Entrants")
        lb = tk.Listbox(top, selectmode=tk.MULTIPLE, width=40, height=15)
        lb.pack(side=tk.LEFT, padx=8, pady=8)
        sb = ttk.Scrollbar(top, orient=tk.VERTICAL, command=lb.yview)
        sb.pack(side=tk.RIGHT, fill=tk.Y)
        lb.config(yscrollcommand=sb.set)

        # Build eligible list
        existing_ids = {int(self._entrants_tree.item(i, "values")[0]) for i in self._entrants_tree.get_children()}
        if ev.type == "Team":
            candidates = self.td.teams.items()
        else:
            candidates = self.td.individuals.items()
        items = []
        for pid, p in candidates:
            if pid in existing_ids:
                continue
            if getattr(p, 'one_event_only', False) and p.chosen_event_id is not None and p.chosen_event_id != eid:
                continue
            items.append((pid, p.name))
        for pid, name in items:
            lb.insert(tk.END, f"{pid}: {name}")

        def add_selected():
            for idx in lb.curselection():
                text = lb.get(idx)
                pid = int(text.split(":", 1)[0])
                name = text.split(":", 1)[1].strip()
                self._entrants_tree.insert("", tk.END, values=(pid, name))
            top.destroy()

        ttk.Button(top, text="Add", command=add_selected).pack(pady=6)

    def _save_results_for_event(self):
        try:
            eid = self._parse_event_combo_value(self.res_event.get())
            if eid is None or eid not in self.td.events:
                raise ValueError("Select a valid event.")
            pids = [int(self._entrants_tree.item(i, "values")[0]) for i in self._entrants_tree.get_children()]
            self.td.set_event_results(eid, pids)
            messagebox.showinfo("Saved", "Results saved for event.")
            self._refresh_leaderboards()
        except Exception as e:
            messagebox.showerror("Save Results Error", str(e))

    # -------------------------
    # Leaderboards
    # -------------------------
    def _refresh_leaderboards(self):
        teams, indivs = self.td.compute_leaderboards()
        # Teams
        self._clear_tree(self._team_lb)
        for tid, pts in teams:
            name = self.td.teams.get(tid).name if tid in self.td.teams else f"Team {tid}"
            self._team_lb.insert("", tk.END, values=(name, pts))
        # Individuals
        self._clear_tree(self._indiv_lb)
        for iid, pts in indivs:
            name = self.td.individuals.get(iid).name if iid in self.td.individuals else f"Player {iid}"
            self._indiv_lb.insert("", tk.END, values=(name, pts))

    # -------------------------
    # Utilities
    # -------------------------
    def _clear_tree(self, tree: ttk.Treeview):
        for i in tree.get_children():
            tree.delete(i)

    def _refresh_all(self):
        self._refresh_participants_trees()
        self._refresh_events_tree()
        self._refresh_event_dropdowns()
        self._refresh_leaderboards()


if __name__ == "__main__":
    app = TournamentApp()
    app.mainloop()
```

How to use this GUI, briefly:
- Participants tab: Add teams (name + members) and individuals. Toggle “One event only” and optionally set their chosen event from the dropdown after you’ve created events. Names must be unique; teams can have up to 5 members; max 4 teams and 20 individuals.
- Events tab: Define up to 5 Team and 5 Individual events. Optionally enter a per-event points override like 1:10,2:7,3:5. If omitted, the global points table applies.
- Results tab: Choose an event, load entrants, then order them top-to-bottom to reflect ranks. One-event-only participants can appear only in their single/chosen event. Save results to update leaderboards.
- Leaderboards tab: Refresh to view aggregated points for teams and individuals.
- Points menu: Edit the global points table using rank:points per line.
- File menu: New/Open/Save As for JSON state.

Edge cases and limitations considered:
- Input validation: unique names, non-empty fields, max sizes, consistent event types, valid points tables (non-increasing).
- One-event-only: enforced when saving results and when loading/adding eligible entrants; chosen event auto-populates on first assignment if not preset.
- Deletions: removing teams/individuals purges them from relevant results; removing events clears its results and chosen-event links.
- Points gaps: ranks beyond defined points get 0; ties are not supported (use shared ranks as adjacent entries or adjust points map accordingly).
- Persistence: JSON schema is simple but not versioned; editing files externally may require revalidation on load.
- Concurrency: single-user desktop UI; no locking across files.
- Scale: UI is sized for the specified limits (4 teams, 20 individuals, 5 events per type).

Here is a complete MATLAB implementation of a 2-D source panel method that reads panel points from a text file, prompts for flow conditions, computes pressure coefficients, estimates lift via Kutta–Joukowski (for symmetric bodies or small angles; see comments), compares against an analytical reference (circular cylinder by default), and varies the number of panels to report accuracy. The code is organized into a main script and helper functions in a single file for convenience.

% ==========================
% File: source_panel_main.m
% ==========================
function source_panel_main()
    clc; close all; clearvars; %#ok<CLSCR>
    fprintf('2-D Source Panel Method (MATLAB)\n');

    % ---- User inputs ----
    try
        geomFile = input('Enter path to geometry text file (x y per line): ', 's');
        if ~isfile(geomFile)
            error('Geometry file not found: %s', geomFile);
        end
        Uinf = inputWithDefault('Enter free-stream speed U_inf [m/s] (default 1): ', 1);
        alpha_deg = inputWithDefault('Enter angle of attack alpha [deg] (default 0): ', 0);
        rho = inputWithDefault('Enter fluid density rho [kg/m^3] (default 1): ', 1);
        nPanelListStr = input('Enter panel counts to test (e.g., "64 128 256"): ', 's');
        if isempty(strtrim(nPanelListStr))
            nPanelList = [64 128 256];
        else
            nPanelList = str2num(nPanelListStr); %#ok<ST2NM>
        end
        if isempty(nPanelList) || any(nPanelList<=2)
            error('Panel counts must be a list of integers > 2.');
        end
    catch ME
        fprintf(2, 'Input error: %s\n', ME.message);
        return;
    end

    alpha = deg2rad(alpha_deg);

    % ---- Read geometry points ----
    try
        P = readPanelPoints(geomFile); % Nx2 array [x y]
    catch ME
        fprintf(2, 'Failed to read geometry: %s\n', ME.message);
        return;
    end

    % Try to detect if geometry is a circle for analytical comparison
    [isCircle, circleData] = detectCircle(P);
    if isCircle
        fprintf('Detected circular cylinder: center=(%.4f, %.4f), R=%.4f\n', circleData.cx, circleData.cy, circleData.R);
    else
        fprintf('No circle detected. Analytical comparisons use flat-plate small-angle approximations where applicable.\n');
    end

    % ---- Loop over panel counts for accuracy study ----
    results = struct('N', {}, 'CL', {}, 'CL_ref', {}, 'CL_err', {}, 'CpL2', {}, 'CpMaxErr', {});

    for k = 1:numel(nPanelList)
        Ntarget = nPanelList(k);
        % Resample geometry to Ntarget points on the closed curve
        try
            Pn = resampleClosedCurve(P, Ntarget);
        catch ME
            fprintf(2, 'Resampling failed for N=%d: %s\n', Ntarget, ME.message);
            continue;
        end

        % Build panels
        panels = buildPanels(Pn);

        % Solve source strengths and compute tangential velocity and Cp
        try
            [sigma, Vt, Cp, S, nx, ny, xc, yc, theta] = sourcePanelSolve(panels, Uinf, alpha); %#ok<ASGLU>
        catch ME
            fprintf(2, 'Panel solve failed for N=%d: %s\n', Ntarget, ME.message);
            continue;
        end

        % Compute lift using Kutta–Joukowski based on circulation from tangential velocity integral
        % Note: Pure source-panel method (no vortex) ideally yields zero net circulation.
        % We estimate an effective circulation from surface tangential velocity integral.
        ds = panels.ds;
        Gamma = -sum(Vt .* ds); % sign by RH rule; consistent with outward normal
        CL = 2*Gamma/(Uinf*referenceChord(Pn)); % 2D lift coefficient based on c_ref

        % Analytical/reference comparisons
        if isCircle
            % Potential flow around cylinder: CL_ref = 2*pi*sin(alpha)
            CL_ref = 2*pi*sin(alpha);
            % Analytical Cp for a cylinder at angle alpha: Cp = 1 - 4*sin^2(theta - alpha)
            thetaNode = theta; % panel control-point angle around cylinder center
            Cp_ref = 1 - 4*(sin(thetaNode - alpha)).^2;
            % Map Cp to panels and compute errors
            [Cp_interp, mask] = mapAnalyticalCpToPanels(Cp_ref, true(size(Cp_ref))); %#ok<ASGLU>
            Cp_err = Cp(mask) - Cp_ref(mask);
            CpL2 = sqrt(mean(Cp_err.^2));
            CpMaxErr = max(abs(Cp_err));
            CL_err = abs(CL - CL_ref);
        else
            % No solid analytical Cp/CL; use small-angle flat-plate CL ~ 2*pi*alpha as a rough reference if geometry is slender
            if isSlender(Pn)
                CL_ref = 2*pi*alpha; % very rough thin-airfoil estimate
            else
                CL_ref = NaN;
            end
            CpL2 = NaN; CpMaxErr = NaN; CL_err = abs(CL - CL_ref);
        end

        % Store results
        results(end+1) = struct('N', Ntarget, 'CL', CL, 'CL_ref', CL_ref, ...
                                'CL_err', CL_err, 'CpL2', CpL2, 'CpMaxErr', CpMaxErr); %#ok<AGROW>

        % Report
        fprintf('N=%4d | CL= %+8.5f | CL_ref= %+8.5f | |dCL|= %.3e | Cp L2= %.3e | Cp Max= %.3e\n', ...
            Ntarget, CL, CL_ref, CL_err, CpL2, CpMaxErr);

        % Plot Cp distribution
        figure('Name', sprintf('Cp (N=%d)', Ntarget));
        sCoord = [0; cumsum(ds)]; sCoord = sCoord(1:end-1); sCoord = sCoord / sCoord(end);
        plot(sCoord, Cp, 'o-', 'DisplayName', 'Computed'); hold on; grid on;
        if isCircle
            plot(sCoord, Cp_ref, 'k--', 'DisplayName', 'Analytical');
        end
        set(gca, 'YDir', 'reverse');
        xlabel('Non-dimensional arc length s/L'); ylabel('Cp'); legend('Location','best');
        title(sprintf('Pressure coefficient distribution (N=%d)', Ntarget));
    end

    % Summary table
    if ~isempty(results)
        fprintf('\nSummary (increasing N):\n');
        fprintf('   N      CL         CL_ref      |dCL|       CpL2        CpMax\n');
        for i = 1:numel(results)
            r = results(i);
            fprintf('%5d  %+9.5f  %+9.5f  %9.3e  %11.3e  %11.3e\n', r.N, r.CL, r.CL_ref, r.CL_err, r.CpL2, r.CpMaxErr);
        end
    end

    fprintf('\nDone.\n');
end

% -------- Helper: prompt with default --------
function val = inputWithDefault(prompt, defaultVal)
    s = input(prompt, 's');
    if isempty(strtrim(s))
        val = defaultVal;
    else
        val = str2double(s);
        if isnan(val)
            error('Invalid numeric input.');
        end
    end
end

% -------- Read panel points from text file --------
function P = readPanelPoints(fname)
    data = readmatrix(fname);
    if size(data,2) < 2
        error('Geometry file must have at least 2 columns (x y).');
    end
    P = data(:,1:2);
    % Ensure closed curve (append first point if needed)
    if norm(P(end,:) - P(1,:)) > 1e-12
        P = [P; P(1,:)];
    end
    % Remove duplicate consecutive points
    d = sqrt(sum(diff(P).^2,2));
    P = P([true; d>eps],:);
    if size(P,1) < 4
        error('Not enough points to form panels.');
    end
end

% -------- Resample closed curve to N points (arc-length) --------
function Pn = resampleClosedCurve(P, N)
    % P is closed (first==last). Create cumulative arc-length
    if norm(P(end,:) - P(1,:)) > 1e-12
        P = [P; P(1,:)];
    end
    s = [0; cumsum(sqrt(sum(diff(P).^2,2)))];
    L = s(end);
    sQuery = linspace(0, L, N+1).';
    xq = interp1(s, P(:,1), sQuery, 'linear');
    yq = interp1(s, P(:,2), sQuery, 'linear');
    Pn = [xq yq];
    % ensure closed
    Pn(end,:) = Pn(1,:);
end

% -------- Build panels (control points, lengths, tangents/normals) --------
function panels = buildPanels(P)
    % Panels between consecutive points; control point at mid-point
    N = size(P,1)-1;
    x = P(:,1); y = P(:,2);
    xA = x(1:N); yA = y(1:N);
    xB = x(2:N+1); yB = y(2:N+1);

    dx = xB - xA; dy = yB - yA;
    ds = hypot(dx, dy);
    theta = atan2(dy, dx); % panel orientation angle w.r.t x-axis

    xc = 0.5*(xA + xB); yc = 0.5*(yA + yB); % control points

    tx = cos(theta); ty = sin(theta); % unit tangent
    nx = -ty; ny = tx;                 % unit outward normal (CCW geometry)

    panels = struct('xA',xA,'yA',yA,'xB',xB,'yB',yB,'xc',xc,'yc',yc, ...
                    'ds',ds,'theta',theta,'tx',tx,'ty',ty,'nx',nx,'ny',ny,'N',N);
end

% -------- Source panel solve (uniform strength per panel) --------
function [sigma, Vt, Cp, S, nx, ny, xc, yc, theta] = sourcePanelSolve(panels, Uinf, alpha)
    % Build influence matrices for source panels
    N = panels.N;
    xc = panels.xc; yc = panels.yc;
    nx = panels.nx; ny = panels.ny; ds = panels.ds; theta = panels.theta;
    xA = panels.xA; yA = panels.yA; xB = panels.xB; yB = panels.yB;

    A = zeros(N,N); RHS = -Uinf*(cos(alpha)*nx + sin(alpha)*ny); % no-penetration

    for i = 1:N
        for j = 1:N
            [I_n, ~] = sourceInfluenceOnControl(xc(i), yc(i), xA(j), yA(j), xB(j), yB(j), theta(j), nx(i), ny(i));
            A(i,j) = I_n;
        end
    end

    % Solve for source strengths (sigma_j are constant per panel)
    sigma = A \ RHS;

    % Compute tangential velocity at control points
    Vt = Uinf*( -sin(alpha)*nx + cos(alpha)*ny ); % free-stream contribution projected to tangent? adjust below
    % Proper projection to tangent direction (tx,ty)
    tx = panels.tx; ty = panels.ty;
    Vt = Uinf*(cos(alpha)*tx + sin(alpha)*ty); % start with free stream tangential component

    % Add source-panel induced tangential velocity
    for i = 1:N
        Vt_ind = 0;
        for j = 1:N
            [~, I_t] = sourceInfluenceOnControl(xc(i), yc(i), xA(j), yA(j), xB(j), yB(j), theta(j), tx(i), ty(i));
            Vt_ind = Vt_ind + sigma(j) * I_t;
        end
        Vt(i) = Vt(i) + Vt_ind;
    end

    % Pressure coefficient
    Cp = 1 - (Vt./Uinf).^2;

    S = sum(ds);
end

% -------- Source influence (normal and tangential) at a control point --------
function [I_n, I_t] = sourceInfluenceOnControl(xp, yp, x1, y1, x2, y2, theta_j, nx_i, ny_i)
    % Transform control point to panel-local coords where panel j lies on x'-axis
    % Panel from (0,0) to (L,0); local normal is +y'
    L = hypot(x2-x1, y2-y1);
    cosT = cos(theta_j); sinT = sin(theta_j);
    % Shift and rotate
    xrel = (xp - x1)*cosT + (yp - y1)*sinT;
    yrel = -(xp - x1)*sinT + (yp - y1)*cosT;

    % Standard 2D source panel integrals (see Hess & Smith)
    % Avoid singularities
    eps0 = 1e-12;
    x2p = L - xrel; x1p = -xrel;
    r1 = hypot(x1p, yrel) + eps0;
    r2 = hypot(x2p, yrel) + eps0;
    th1 = atan2(yrel, x1p);
    th2 = atan2(yrel, x2p);

    % Velocity components in local coords due to unit-strength source panel
    % u' = (1/2pi) * (th2 - th1)
    % v' = (1/2pi) * ln(r2/r1)
    u_loc = (th2 - th1) / (2*pi);
    v_loc = log(r2/r1) / (2*pi);

    % Transform induced velocity back to global
    u =  u_loc*cosT - v_loc*sinT;
    v =  u_loc*sinT + v_loc*cosT;

    % Projections onto given directions (nx_i, ny_i) provided by caller
    I_n = u*nx_i + v*ny_i;

    % For tangential projection, caller passes tangent unit vector in place of (nx_i, ny_i)
    I_t = I_n; % same formula works because we pass desired direction components
end

% -------- Estimate reference chord length (for CL normalization) --------
function c = referenceChord(P)
    % Use max(x)-min(x) as a simple chord-length proxy
    c = max(P(:,1)) - min(P(:,1));
    if c <= 0
        % fallback to perimeter / pi as approximate diameter-like scale
        s = [0; cumsum(sqrt(sum(diff(P).^2,2)))];
        L = s(end);
        c = L/pi;
    end
end

% -------- Detect if point set is approximately a circle --------
function [isCircle, data] = detectCircle(P)
    % Fit circle using linear least squares (Kasa method)
    x = P(:,1); y = P(:,2);
    if norm(P(end,:) - P(1,:)) < 1e-12
        x = x(1:end-1); y = y(1:end-1);
    end
    A = [2*x 2*y ones(size(x))];
    b = x.^2 + y.^2;
    sol = A\b;
    cx = sol(1); cy = sol(2); c0 = sol(3);
    R = sqrt(cx^2 + cy^2 + c0);
    rErr = sqrt(mean((hypot(x-cx, y-cy) - R).^2));
    isCircle = rErr < 1e-3*R; % tolerance
    data = struct('cx',cx,'cy',cy,'R',R);
end

% -------- Map analytical Cp (already at control points for circle) --------
function [Cp_mapped, mask] = mapAnalyticalCpToPanels(Cp_ref, valid)
    Cp_mapped = Cp_ref(:);
    mask = valid(:);
end

% -------- Heuristic slenderness check --------
function tf = isSlender(P)
    xr = max(P(:,1))-min(P(:,1));
    yr = max(P(:,2))-min(P(:,2));
    tf = xr > 3*yr; % crude
end

