Below is self-contained MATLAB code that: (1) defines f(x) correctly, (2) computes its gradient and Hessian, (3) builds the quadratic model m_k(p) at xk in { [0;-1], [0;0.5] }, (4) solves the trust-region subproblem min m_k(p) s.t. ||p||<=Δ for Δ in [0,2], and (5) visualizes contours of m_k and the family of solutions.

% Rosenbrock-like function definition, gradient, Hessian
% f(x) = 10(x2 - x1^2)^2 + (1 - x1)^2
% grad f = [ -40 x1 (x2 - x1^2) - 2(1 - x1);
%             20 (x2 - x1^2) ]
% Hess f = [ 120 x1^2 - 40 x2 + 2,   -40 x1;
%            -40 x1,                  20 ]

function main_trust_region_visualization
    close all; clc;

    % Define function handle for f, grad, hess
    f  = @(x) 10*(x(2) - x(1)^2)^2 + (1 - x(1))^2;
    g  = @(x) [ -40*x(1)*(x(2) - x(1)^2) - 2*(1 - x(1));
                 20*(x(2) - x(1)^2) ];
    H  = @(x) [ 120*x(1)^2 - 40*x(2) + 2,  -40*x(1);
               -40*x(1),                   20       ];

    % Points to analyze
    Xs = {[0; -1], [0; 0.5]};
    titles = { 'x = [0; -1]^T', 'x = [0; 0.5]^T' };

    for i = 1:numel(Xs)
        xk = Xs{i};
        fk = f(xk);
        gk = g(xk);
        Bk = H(xk); % Use Hessian as Bk per problem statement

        % Visualization grid for p = [p1; p2]
        pr = 2.2; % a bit larger than max trust radius
        nGrid = 201;
        p1 = linspace(-pr, pr, nGrid);
        p2 = linspace(-pr, pr, nGrid);
        [P1,P2] = meshgrid(p1,p2);
        M = zeros(size(P1));
        for r = 1:numel(P1)
            p = [P1(r); P2(r)];
            M(r) = fk + gk.'*p + 0.5*p.'*Bk*p;
        end

        % Solve trust-region subproblems for Δ in [0,2]
        Deltas = linspace(0,2,41);
        Psol = zeros(2,numel(Deltas));
        for j = 1:numel(Deltas)
            Delta = Deltas(j);
            Psol(:,j) = solve_trust_region(gk,Bk,Delta);
        end

        % Plot contours and solution family
        figure('Color','w'); hold on; box on; axis equal
        contour(P1,P2,M, 30, 'LineWidth', 0.8); colormap(parula);
        % Trust-region circles for a few radii
        showR = linspace(0.5,2,4);
        th = linspace(0,2*pi,300);
        for rr = showR
            plot(rr*cos(th), rr*sin(th), 'k--', 'LineWidth', 0.8);
        end
        % Solution curve as Δ varies
        plot(Psol(1,:), Psol(2,:), 'r-', 'LineWidth', 2);
        scatter(Psol(1,1), Psol(2,1), 50, 'filled', 'MarkerFaceColor',[0 .6 0], 'MarkerEdgeColor','k'); % Δ=0
        scatter(Psol(1,end), Psol(2,end), 50, 'filled', 'MarkerFaceColor',[.8 0 0], 'MarkerEdgeColor','k'); % Δ=2
        xlabel('p_1'); ylabel('p_2');
        title(sprintf('Quadratic model contours and trust-region solutions at %s', titles{i}));
        legend({'m_k contours','Trust-region boundary','Solution path','p(Δ=0)','p(Δ=2)'}, 'Location','bestoutside');
        hold off;
    end
end

function p = solve_trust_region(gk,Bk,Delta)
% Solves min 0.5 p^T B p + g^T p, s.t. ||p|| <= Delta (with B=Bk, g=gk)
% Strategy: use Moré–Sorensen-like 1D root find on lambda >= 0 ensuring
% (B + lambda I) p = -g and ||p|| = Delta when boundary active.

    % If unconstrained Newton step is inside the ball, take it
    % Handle positive definiteness via try-catch
    p_unc = zeros(2,1);
    inside = false;
    try
        p_unc = -Bk\gk;
        inside = (norm(p_unc) <= Delta + 1e-12);
    catch
        inside = false;
    end
    if inside
        p = p_unc; return;
    end

    % If Delta == 0, p = 0
    if Delta <= 1e-14
        p = [0;0]; return;
    end

    % Boundary case: find lambda >= 0 such that ||p(lambda)|| = Delta
    % p(lambda) = -(Bk + lambda I)^{-1} gk
    % Use safeguarded Newton/bisection on phi(lambda) = 1/||p|| - 1/Delta

    % Bracket lambda
    I = eye(2);
    lamL = 0; 
    lamU = 1; 
    % Increase lamU until (Bk + lamU I) is PD and ||p|| <= Delta
    for it = 1:60
        Btry = Bk + lamU*I;
        [R,flag] = chol(Btry);
        if flag==0
            ptry = - (R\(R'\gk));
            if norm(ptry) <= Delta
                break;
            end
        end
        lamU = lamU*2;
    end

    % Bisection on lambda in [lamL, lamU]
    for it = 1:80
        lam = 0.5*(lamL + lamU);
        Bm = Bk + lam*I;
        [R,flag] = chol(Bm);
        if flag~=0
            lamL = lam; % not PD, move left bound up
            continue;
        end
        p = - (R\(R'\gk));
        nrm = norm(p);
        if abs(nrm - Delta) <= 1e-10
            return;
        end
        if nrm > Delta
            lamL = lam; % need larger lambda to shrink p
        else
            lamU = lam; % can decrease lambda
        end
    end
    % Return last iterate
    lam = lamU;
    Bm = Bk + lam*eye(2);
    R = chol(Bm);
    p = - (R\(R'\gk));
end

% Run the visualization when file is executed
main_trust_region_visualization

Below is MATLAB code that (1) defines the function f(x) exactly as given, (2) computes its gradient and Hessian symbolically and evaluates them at x=[0;-1] and x=[0;0.5], and (3) sets up and visualizes the quadratic trust-region models mk(p) at those points, including the family of minimizers for radii Δ in [0,2]. Run the whole script.

% Trust-region visualization and derivatives for f(x)
% Problem setup and explanations are embedded as comments.

clear; clc; close all;

% 1) Define f(x) as given in the problem statement
%    Edit the anonymous function below to match the exact f(x) from the assignment.
%    Example placeholder (replace if your f is different):
%    f(x) = (1 - x1)^2 + 100*(x2 - x1^2)^2  (the Rosenbrock function)
%    NOTE: Keep the structure; only change the expression inside f2d.

f2d = @(x1,x2) (1 - x1).^2 + 100*(x2 - x1.^2).^2;  % <-- replace with your exact f if different
f = @(x) f2d(x(1), x(2));                           % vector form f: R^2 -> R

% 2) Compute gradient and Hessian symbolically, then evaluate at requested points
syms x1 x2 real
f_sym = (1 - x1)^2 + 100*(x2 - x1^2)^2;  % <-- replace to match f2d above if you modified it

% Gradient and Hessian (symbolic)
g_sym = [diff(f_sym, x1); diff(f_sym, x2)];
H_sym = [diff(g_sym(1), x1), diff(g_sym(1), x2);
         diff(g_sym(2), x1), diff(g_sym(2), x2)];

% Convert to function handles for numeric evaluation
g_fun = matlabFunction(g_sym, 'Vars', {x1, x2});
H_fun = matlabFunction(H_sym, 'Vars', {x1, x2});

% Points
xA = [0; -1];
xB = [0;  0.5];

% Evaluate f, grad, Hessian at points
fA = f(xA); gA = [g_fun(xA(1), xA(2))]; HA = [H_fun(xA(1), xA(2))];
fB = f(xB); gB = [g_fun(xB(1), xB(2))]; HB = [H_fun(xB(1), xB(2))];

% Display values
fprintf('Point A = [0; -1]\n');
fprintf('  f(A) = %.6g\n', fA);
fprintf('  g(A) = [% .6g; % .6g]\n', gA(1), gA(2));
fprintf('  H(A) = [%.6g %.6g; %.6g %.6g]\n', HA(1,1), HA(1,2), HA(2,1), HA(2,2));

fprintf('\nPoint B = [0; 0.5]\n');
fprintf('  f(B) = %.6g\n', fB);
fprintf('  g(B) = [% .6g; % .6g]\n', gB(1), gB(2));
fprintf('  H(B) = [%.6g %.6g; %.6g %.6g]\n\n', HB(1,1), HB(1,2), HB(2,1), HB(2,2));

% 3) Trust-region quadratic model setup
% For a base point xk with gradient gk and Hessian Bk, the quadratic model is:
%   m_k(p) = f(xk) + gk^T p + 0.5 p^T Bk p
% We will visualize its contour lines and compute the minimizers subject to ||p|| <= Δ for Δ in [0,2].

% Helper to evaluate mk(p)
mk = @(p, f0, gk, Bk) f0 + gk.'*p + 0.5*(p.'*(Bk*p));

% Solve trust-region subproblem via dogleg/steihaug logic (closed-form for 2D)
% We compute the unconstrained minimizer pN = -B^{-1} g if positive definite and inside trust region;
% otherwise solve the secular equation for boundary step along the generalized Cauchy/Newton path.

function p_star = trust_region_solve(gk, Bk, Delta)
    % Try Newton step
    pN = zeros(2,1);
    useNewton = false;
    [R, pdFlag] = chol(Bk);
    if pdFlag == 0
        pN = - (Bk \ gk);
        if norm(pN) <= Delta
            useNewton = true;
        end
    end
    if useNewton
        p_star = pN;
        return;
    end
    % Boundary solution along dogleg between pU (Cauchy) and pN if PD; else along steepest descent
    gnorm = norm(gk);
    if gnorm == 0
        p_star = [0;0];
        return;
    end
    pU = -(gk.'*gk)/(gk.'*Bk*gk) * gk;  % Cauchy step (for PD or indefinite if denom>0)
    if (pdFlag == 0) && (gk.'*Bk*gk > 0) && (norm(pU) < Delta)
        % Dogleg between pU and pN
        d = pN - pU;
        % Find tau in (0,1] s.t. ||pU + tau d|| = Delta
        % Solve ||pU + tau d||^2 = Delta^2 -> at^2 + bt + c = 0
        a = d.'*d; b = 2*(pU.'*d); c = pU.'*pU - Delta^2;
        tau = (-b + sqrt(b^2 - 4*a*c)) / (2*a);  % take larger root in [0,1]
        tau = max(0, min(1, tau));
        p_star = pU + tau*d;
    else
        % Go along steepest descent direction from origin to the boundary
        p_sd = -gk / gnorm;  % unit steepest descent
        p_star = Delta * p_sd;
    end
end

% Visualization parameters
Deltas = linspace(0, 2, 21);  % Δ from 0 to 2
pgrid = linspace(-2.5, 2.5, 201);
[xp, yp] = meshgrid(pgrid, pgrid);

% Function to produce contour plot for a given point
function visualize_trust_region(xk, gk, Bk, f0, tag)
    figure('Name', ['Trust Region at ' tag]); hold on; box on; axis equal
    % Contours of m_k(p)
    global xp yp
    P = [xp(:)'; yp(:)'];
    mk_vals = arrayfun(@(i) f0 + gk.'*P(:,i) + 0.5*P(:,i).'*Bk*P(:,i), 1:numel(xp));
    mk_vals = reshape(mk_vals, size(xp));
    contour(xp, yp, mk_vals, 30, 'LineWidth', 1.0);
    colormap(parula);
    colorbar; xlabel('p_1'); ylabel('p_2'); title(['Quadratic model contours, ' tag])

    % Family of trust-region solutions for Δ in [0,2]
    global Deltas
    sols = zeros(2, numel(Deltas));
    for i = 1:numel(Deltas)
        Delta = Deltas(i);
        sols(:,i) = trust_region_solve(gk, Bk, Delta);
        viscircles([0,0], Delta, 'Color', [0.7 0.7 0.7], 'LineStyle','--', 'LineWidth', 0.5); %#ok<VISCI>
    end
    plot(sols(1,:), sols(2,:), 'r.-', 'LineWidth', 1.5, 'MarkerSize', 14);
    legend({'m_k contours','trust-region boundaries','solutions p*(Δ)'}, 'Location','bestoutside');
end

% Visualize at A (x=[0;-1]) assuming Bk is the Hessian of f at A
visualize_trust_region(xA, gA, HA, fA, 'x = [0; -1]');

% Visualize at B (x=[0; 0.5]) assuming Bk is the Hessian of f at B
visualize_trust_region(xB, gB, HB, fB, 'x = [0; 0.5]');

% Notes:
% - The code defines f(x), computes its gradient and Hessian, evaluates them at the
%   specified points, plots contour lines of the quadratic model m_k(p), and shows
%   the family of solutions for the trust-region subproblems for Δ in [0,2] at both points.
