src/lookup/lookup.controller.ts (in-memory mode)
```ts
import { Controller, Get, Post, Query, Req, HttpException, HttpStatus } from '@nestjs/common';
import { readFile } from 'node:fs/promises';
import { buildStoreFromXml, lookup, InMemoryStore } from './indexer';

let STORE: InMemoryStore | null = null;
let RELOADING = false;

async function loadStore(): Promise<void> {
  const xml = await readFile(process.env.XML_PATH || '/app/data/records.xml', 'utf-8');
  STORE = await buildStoreFromXml(xml, {
    primaryKey: process.env.PRIMARY_KEY_FIELD || 'id',
    indexFields: (process.env.LOOKUP_INDEX_FIELDS || 'code').split(',').map(s => s.trim()).filter(Boolean),
    recordPath: process.env.XML_RECORD_PATH || 'records.record'
  });
}

@Controller('lookup')
export class LookupController {
  constructor() { if (!STORE) loadStore().catch(console.error); }

  @Get()
  async get(@Query('field') field: string, @Query('value') value: string) {
    if (!STORE) throw new HttpException('Service warming up', HttpStatus.SERVICE_UNAVAILABLE);
    if (!field || value == null) throw new HttpException('field and value required', HttpStatus.BAD_REQUEST);
    if (!STORE.indexes[field]) throw new HttpException('Unknown field', HttpStatus.BAD_REQUEST);
    return lookup(STORE, field, value);
  }

  @Get('fields')
  fields() {
    if (!STORE) throw new HttpException('Service warming up', HttpStatus.SERVICE_UNAVAILABLE);
    return { fields: Object.keys(STORE.indexes) };
  }

  @Get('count')
  count() {
    if (!STORE) throw new HttpException('Service warming up', HttpStatus.SERVICE_UNAVAILABLE);
    return { count: STORE!.records.length };
  }

  @Post('reload')
  async reload(@Req() req) {
    const token = req.headers['x-admin-token'];
    if (token !== (process.env.RELOAD_TOKEN || 'change-me')) {
      throw new HttpException('Forbidden', HttpStatus.FORBIDDEN);
    }
    if (RELOADING) return { status: 'already_reloading' };
    RELOADING = true;
    try {
      await loadStore();
      return { status: 'ok' };
    } finally {
      RELOADING = false;
    }
  }
}
