export const RecordSchema = new Schema({}, {
  strict: false,
  minimize: false,
  versionKey: false
});

export async function ensureMongoIndexes(model: Model<any>) {
  const pk = process.env.PRIMARY_KEY_FIELD || 'id';
  const fields = (process.env.LOOKUP_INDEX_FIELDS || 'code').split(',').map(s => s.trim()).filter(Boolean);
  await model.collection.createIndex({ [pk]: 1 }, { name: `idx_${pk}` });
  for (const f of fields) {
    await model.collection.createIndex({ [f]: 1 }, { name: `idx_${f}` });
  }
}
