import { Controller, Get, HttpException, HttpStatus, Query } from '@nestjs/common';
import { InjectModel } from '@nestjs/mongoose';
import { Model } from 'mongoose';

@Controller('lookup')
export class LookupMongoController {
  private readonly allowed: Set<string>;
  constructor(@InjectModel('Record') private readonly rec: Model<any>) {
    this.allowed = new Set([
      process.env.PRIMARY_KEY_FIELD || 'id',
      ...(process.env.LOOKUP_INDEX_FIELDS || 'code').split(',').map(s => s.trim()).filter(Boolean)
    ]);
  }

  @Get()
  async get(@Query('field') field: string, @Query('value') value: string) {
    if (!field || value == null) throw new HttpException('field and value required', HttpStatus.BAD_REQUEST);
    if (!this.allowed.has(field)) throw new HttpException('Unknown field', HttpStatus.BAD_REQUEST);
    return this.rec.find({ [field]: value }).limit(100).lean();
  }

  @Get('fields')
  fields() { return { fields: Array.from(this.allowed) }; }

  @Get('count')
  async count() { return { count: await this.rec.estimatedDocumentCount() }; }
}
