// src/items/items.service.ts
import { Injectable, Inject } from '@nestjs/common';
import { ClientProxy } from '@nestjs/microservices';

@Injectable()
export class ItemsService {
  private store = new Map<string, any>();

  constructor(@Inject('EVENT_BUS') private readonly bus: ClientProxy) {}

  getById(id: string) { return this.store.get(id) ?? null; }

  async create(dto: { name: string; code?: string; status: string }) {
    const id = dto.code || `${Date.now()}`;
    const rec = { id, ...dto };
    this.store.set(id, rec);
    // Publish event; transport (RMQ/Kafka/NATS) can change via config
    this.bus.emit('item.created', { id, name: dto.name, status: dto.status }).subscribe();
    return rec;
  }
}
