```python
# src/lookup/indexer.ts
import { XMLParser } from 'fast-xml-parser';

type IndexMap = Map<string, any[]>;
type FieldIndex = Record<string, IndexMap>;

export interface BuildOptions {
  primaryKey: string;
  indexFields: string[];
  recordPath: string; // dot path to array in parsed XML
  normalizer?: (v: any) => string;
}
export interface InMemoryStore {
  records: any[];
  byId: Map<string, any>;
  indexes: FieldIndex; // field -> (normalized value -> [records])
}

export const defaultNormalizer = (v: any) =>
  typeof v === 'string' ? v.normalize('NFC').trim().toLowerCase() : String(v);

const getByPath = (obj: any, path: string) =>
  path.split('.').reduce((acc, k) => (acc ? acc[k] : undefined), obj);

export async function buildStoreFromXml(xmlText: string, opts: BuildOptions): Promise<InMemoryStore> {
  const normalizer = opts.normalizer ?? defaultNormalizer;
  const parser = new XMLParser({ ignoreAttributes: false, trimValues: true });
  const parsed = parser.parse(xmlText);
  const arr = getByPath(parsed, opts.recordPath);
  if (!Array.isArray(arr)) throw new Error(`XML_RECORD_PATH not an array: ${opts.recordPath}`);

  const records = arr;
  const byId = new Map<string, any>();
  const indexes: FieldIndex = {};
  const allFields = Array.from(new Set([opts.primaryKey, ...opts.indexFields]));
  for (const f of allFields) indexes[f] = new Map();

  for (const r of records) {
    for (const f of allFields) {
      const raw = r[f];
      if (raw == null) continue;
      const key = normalizer(raw);
      if (f === opts.primaryKey) byId.set(key, r);
      const list = indexes[f].get(key);
      if (list) list.push(r); else indexes[f].set(key, [r]);
    }
  }
  return { records, byId, indexes };
}

export function lookup(store: InMemoryStore, field: string, value: string) {
  const map = store.indexes[field];
  if (!map) return [];
  return map.get(defaultNormalizer(value)) || [];
}
