ALLOWED_MIME = {"text/plain", "application/pdf"}
MAX_TEXT_LEN = 40_000  # characters safety cap


def validate_upload(file_storage) -> Optional[str]:
    if not file_storage:
        return "No file provided."
    filename = (file_storage.filename or "").lower()
    if not filename:
        return "Missing filename."
    if not (filename.endswith(".txt") or filename.endswith(".pdf")):
        return "Only .txt or .pdf files are allowed."
    # Rely on MAX_CONTENT_LENGTH for global cap; also check mimetype defensively.
    mime = (file_storage.mimetype or "").split(";")[0].strip()
    if mime not in ALLOWED_MIME and not (filename.endswith(".txt") and mime in {"application/octet-stream", "text/plain"}):
        return "Invalid file type. Please upload .txt or .pdf."
    return None


