@app.post("/embed")
def embed_submit():
    # Strict server-side validation
    text = (request.form.get("recipe_text") or "").strip()
    file = request.files.get("recipe_file")

    if not text and (not file or (file and not file.filename)):
        return error_page("Please paste recipe text or upload a .txt/.pdf file.")

    raw_text = ""
    if text:
        if len(text) > MAX_TEXT_LEN:
            return error_page(f"Pasted text is too long (>{MAX_TEXT_LEN} chars). Please shorten it.")
        raw_text = text

    elif file and file.filename:
        err = validate_upload(file)
        if err:
            return error_page(err)
        try:
            data = file.read()
            if not data:
                return error_page("Uploaded file is empty.")
            # Additional defensive size check (Flask already enforces MAX_CONTENT_LENGTH)
            if len(data) > app.config["MAX_CONTENT_LENGTH"]:
                return error_page("Uploaded file exceeds 2 MB limit.")
            if file.filename.lower().endswith(".pdf"):
                try:
                    raw_text = extract_text_from_pdf(data)
                except RuntimeError as e:
                    return error_page(str(e))
            else:
                # Assume UTF-8 with replacement for safety
                raw_text = data.decode("utf-8", errors="replace")
        except Exception as e:
            logger.exception("Failed to process upload")
            return error_page("We couldn't read the uploaded file. Please try a plain .txt or a simple PDF.")

    # Parse ingredients
    ingredients = extract_ingredients_from_text(raw_text)
    if not ingredients:
        return error_page("We couldn't find any ingredients. Please include a clear Ingredients list or bullet points.")

    # Lookups with caching
    lore: Dict[str, Dict] = {}
    for ing in ingredients:
        try:
            lore[ing] = fetch_knowledge_for_ingredient(ing)
        except Exception:
            lore[ing] = {"adjectives": [], "related": []}

    # Build spell
    spell = build_spell(ingredients, lore)

    # Render result page
    items = "".join(f"<li>{html.escape(ing)}</li>" for ing in ingredients)
    sources_html = "".join(
        f"<li><a target=_blank rel=noopener href='{html.escape(data['sources']['wikipedia'])}'>Wikipedia: {html.escape(ing)}</a></li>"
        for ing, data in lore.items()
    )

    body = f"""
    <div class=card>
      <h1>Your Spell</h1>
      <div class=ok>Success! We found {len(ingredients)} ingredient(s).</div>
      <h2>Ingredients</h2>
      <ul>{items}</ul>
      <h2>Incantation</h2>
      <pre style="white-space:pre-wrap">{html.escape(spell)}</pre>
      <details>
        <summary class="small">Sources and lookups</summary>
        <ul>{sources_html}</ul>
        <p class="small muted">Lookups use Wikipedia, Wikidata, and Datamuse with short timeouts for speed.</p>
      </details>
      <p><a class=btn href="/embed">Try another recipe</a></p>
    </div>
    """
    return page("Spell Result", body)


def error_page(message: str, status: int = 400):
    body = f"""
    <div class=card>
      <h1>We hit a snag</h1>
      <div class=error>{html.escape(message)}</div>
      <p class=muted>Tips: Paste the ingredients list or upload a small .txt/.pdf file under 2 MB.</p>
      <p><a class=btn href="/embed">Go back</a></p>
    </div>
    """
    return page("Error", body, status=status)


