phSize          = input.string("xlarge", "Pivot High size", options=["tiny","small","normal","large","xlarge","huge"]) 
plSize          = input.string("xlarge", "Pivot Low size",  options=["tiny","small","normal","large","xlarge","huge"]) 

//========================
// Pivot detection
//========================
ph = ta.pivothigh(high, leftLen, rightLen)
pl = ta.pivotlow(low,  leftLen, rightLen)

isPH = not na(ph)
isPL = not na(pl)

//========================
// Plot regular pivots (clearly visible markers)
//========================
// We plot shapes at the bar where the pivot is confirmed (current bar - rightLen)
var label phLbl = na
var label plLbl = na

if showPivots and isPH
    barIndexForPH = bar_index - rightLen
    phPrice       = ph
    label.delete(phLbl)
    phLbl := label.new(barIndexForPH, phPrice, text="PH", style=label.style_label_down, color=color.new(pivotHighColor, 0), textcolor=color.white, size=size.size(phSize))

if showPivots and isPL
    barIndexForPL = bar_index - rightLen
    plPrice       = pl
    label.delete(plLbl)
    plLbl := label.new(barIndexForPL, plPrice, text="PL", style=label.style_label_up, color=color.new(pivotLowColor, 0), textcolor=color.white, size=size.size(plSize))

//========================
// Missed pivot logic
//========================
// Definition used here:
// - A pivot high is considered "missed" if, after it confirms, price trades above that pivot price within a lookahead window.
// - A pivot low is considered "missed" if, after it confirms, price trades below that pivot price within a lookahead window.
// Users typically want immediate alerts once the breach happens; use the confirmation bar forward.
missLookaheadBars = input.int(200, "Bars to watch for missed pivot", minval=1)

// Track most recent confirmed pivot prices and their confirmation bar indices
var float lastPHPrice = na
var float lastPLPrice = na
var int   lastPHBar   = na
var int   lastPLBar   = na

if isPH
    lastPHPrice := ph
    lastPHBar   := bar_index

if isPL
    lastPLPrice := pl
    lastPLBar   := bar_index

// Conditions for missed pivots within the lookahead window
inPHWindow = not na(lastPHBar) and bar_index - lastPHBar <= missLookaheadBars
inPLWindow = not na(lastPLBar) and bar_index - lastPLBar <= missLookaheadBars

missedPH = inPHWindow and not na(lastPHPrice) and high > lastPHPrice
missedPL = inPLWindow and not na(lastPLPrice) and low  < lastPLPrice

//========================
// On-chart warnings for regular pivots and missed pivots
//========================
// Regular pivot annotations are already labeled above.
// Add subtle lines at last confirmed pivots to help visualize breaches.
var line lastPHLine = na
var line lastPLLine = na

if isPH
    line.delete(lastPHLine)
    lastPHLine := line.new(bar_index - rightLen, ph, bar_index, ph, extend=extend.right, color=color.new(pivotHighColor, 65), width=2, style=line.style_dotted)

if isPL
    line.delete(lastPLLine)
    lastPLLine := line.new(bar_index - rightLen, pl, bar_index, pl, extend=extend.right, color=color.new(pivotLowColor, 65), width=2, style=line.style_dotted)

// Optional on-chart warning markers when a missed pivot occurs
missWarnColorPH = color.new(color.orange, 0)
missWarnColorPL = color.new(color.teal,   0)
plotshape(missedPH, title="Missed Pivot High Warning", style=shape.triangledown, color=missWarnColorPH, size=size.large, location=location.abovebar, text="Missed PH")
plotshape(missedPL, title="Missed Pivot Low Warning",  style=shape.triangleup,   color=missWarnColorPL, size=size.large, location=location.belowbar, text="Missed PL")

//========================
// Alertconditions with user toggles
//========================
alertcondition(missedPHAlerts and missedPH, title="Missed Pivot High", message="Missed Pivot High: price broke above last pivot high.")
alertcondition(missedPLAlerts and missedPL, title="Missed Pivot Low",  message="Missed Pivot Low: price broke below last pivot low.")

