    ```js
    // main.js
    import { updatePhysics } from './core/physics.js';
    import { renderFrame, resizeIfNeeded } from './render/canvasRenderer.js';
    import { getState } from './core/state.js';

    const FIXED_DT = 1 / 60;           // seconds of sim time per physics step (tunable by speed)
    const MAX_STEPS = 8;               // safety cap per frame
    let lastRealT = performance.now() / 1000;
    let accumulator = 0;

    function frame() {
      const state = getState();
      const now = performance.now() / 1000;
      let realDt = now - lastRealT;
      lastRealT = now;

      // Clamp dt to avoid giant jumps on tab switch
      realDt = Math.min(realDt, 0.25);

      // Advance sim time by timeScale (speed multiplier)
      accumulator += realDt * state.timeScale;

      let steps = 0;
      while (accumulator >= FIXED_DT && steps < MAX_STEPS) {
        updatePhysics(FIXED_DT); // advance all bodies by FIXED_DT seconds
        accumulator -= FIXED_DT;
        steps++;
      }

      // Ensure canvas matches DPR and element size
      resizeIfNeeded();

      // Render with interpolation alpha (for smoothness if desired)
      const alpha = accumulator / FIXED_DT; // can be used for interpolated rendering
      renderFrame(alpha);

      requestAnimationFrame(frame);
    }

    // Start/stop controlled elsewhere; start by default
    requestAnimationFrame(frame);
