    2) DPR-aware canvas setup (scene + labels)
    (Place in render/canvasRenderer.js; assumes two canvases: sceneCanvas and labelCanvas.)
    ```js
    // render/canvasRenderer.js
    import tinycolor from 'tinycolor2';
    import { worldToScreen, getView } from './scale.js';
    import { bodies } from '../data/bodies.js'; // array of { id, pos: [x,y], radius, color }

    const sceneCanvas = document.getElementById('sceneCanvas');
    const labelCanvas = document.getElementById('labelCanvas');
    const sceneCtx = sceneCanvas.getContext('2d');
    const labelCtx = labelCanvas.getContext('2d', { alpha: true });

    let lastDevicePixelRatio = 0;

    export function resizeIfNeeded() {
      const dpr = window.devicePixelRatio || 1;
      const cssW = sceneCanvas.clientWidth | 0;
      const cssH = sceneCanvas.clientHeight | 0;
      const needResize = (
        dpr !== lastDevicePixelRatio ||
        sceneCanvas.width !== Math.max(1, cssW * dpr) ||
        sceneCanvas.height !== Math.max(1, cssH * dpr)
      );
      if (needResize) {
        lastDevicePixelRatio = dpr;
        const w = Math.max(1, cssW * dpr);
        const h = Math.max(1, cssH * dpr);
        sceneCanvas.width = w; sceneCanvas.height = h;
        labelCanvas.width = w; labelCanvas.height = h;
        sceneCtx.setTransform(1, 0, 0, 1, 0, 0);
        labelCtx.setTransform(1, 0, 0, 1, 0, 0);
        sceneCtx.scale(dpr, dpr);
        labelCtx.scale(dpr, dpr);
      }
    }

    export function renderFrame(alpha = 0) {
      const { zoom, pan } = getView();
      const cssW = sceneCanvas.clientWidth | 0;
      const cssH = sceneCanvas.clientHeight | 0;

      // Clear
      sceneCtx.clearRect(0, 0, cssW, cssH);
      labelCtx.clearRect(0, 0, cssW, cssH);

      // Draw Sun glow
      const sun = bodies.find(b => b.id === 'sun');
      if (sun) {
        const [sx, sy] = worldToScreen(sun.pos);
        const grad = sceneCtx.createRadialGradient(sx, sy, 0, sx, sy, 80);
        grad.addColorStop(0, '#ffd27a');
        grad.addColorStop(1, 'rgba(255,210,122,0)');
        sceneCtx.fillStyle = grad;
        sceneCtx.beginPath();
        sceneCtx.arc(sx, sy, 80, 0, Math.PI * 2);
        sceneCtx.fill();
      }

      // Draw planets (basic culling example)
      for (const b of bodies) {
        if (b.id === 'sun') continue;
        const [x, y] = worldToScreen(b.pos);
        if (x < -20 || y < -20 || x > cssW + 20 || y > cssH + 20) continue; // cull offscreen
        sceneCtx.fillStyle = b.color;
        sceneCtx.beginPath();
        sceneCtx.arc(x, y, Math.max(1.5, Math.sqrt(b.radius) * 0.05), 0, Math.PI * 2);
        sceneCtx.fill();
      }
    }
