    3) Basic hit-testing and label collision with rbush
    (Place in render/labelManager.js; simple example that builds boxes and avoids overlaps.)
    ```js
    // render/labelManager.js
    import RBush from 'rbush';
    import { worldToScreen } from './scale.js';

    const tree = new RBush();

    export function layoutLabels(ctx, bodies, options = {}) {
      const padding = options.padding ?? 2;
      const items = [];
      tree.clear();

      for (const b of bodies) {
        const [x, y] = worldToScreen(b.pos);
        // Skip tiny bodies (LOD)
        if (b.pixelSize && b.pixelSize < 2) continue;

        const text = b.name || b.id;
        ctx.font = '12px system-ui';
        const w = Math.ceil(ctx.measureText(text).width);
        const h = 14; // approx line height
        const lx = x + 8; // offset label to the right
        const ly = y - 8;
        const box = { minX: lx - padding, minY: ly - h - padding, maxX: lx + w + padding, maxY: ly + padding, text, x: lx, y: ly };

        // Check collisions
        const hits = tree.search(box);
        if (hits.length === 0) {
          tree.insert(box);
          items.push(box);
        }
      }

      // Draw labels
      ctx.fillStyle = '#ddd';
      ctx.strokeStyle = 'rgba(0,0,0,0.6)';
      for (const it of items) {
        // halo
        ctx.lineWidth = 3;
        ctx.strokeText(it.text, it.x, it.y);
        // text
        ctx.fillText(it.text, it.x, it.y);
      }
    }
